import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    A = int(input_data[0])
    B = int(input_data[1])
    C = int(input_data[2])
    D = int(input_data[3])

    possible = False
    k = 1
    while k * D <= C:
        milk = C - k * D
        if A <= milk <= B:
            possible = True
            break
        k += 1

    if possible:
        print('S')
    else:
        print('N')

if __name__ == '__main__':
    main()
